@Test
public void testDeprecated_parsesAllOptions() {
    TestContext ctx = createTestContext();

    assertTrue(ctx.cl.hasOption(ctx.opt1.getOpt()),
            "Option 'd1' should be present after parsing");
    assertTrue(ctx.cl.hasOption(ctx.opt2.getOpt()),
            "Option 'd2' should be present after parsing");
    assertTrue(ctx.cl.hasOption(ctx.opt3.getOpt()),
            "Option 'a' should be present after parsing");
}

@Test
public void testDeprecated_handlerInvocation() {
    TestContext ctx = createTestContext();

    assertTrue(ctx.handler.contains(ctx.opt1),
            "Handler should be invoked for deprecated option 'd1'");
    assertTrue(ctx.handler.contains(ctx.opt2),
            "Handler should be invoked for deprecated option 'd2'");
    assertFalse(ctx.handler.contains(ctx.opt3),
            "Handler should NOT be invoked for non‑deprecated option 'a'");
}

/* -------------------------------------------------
   Helper methods and holder class for test setup
   ------------------------------------------------- */
private static class TestContext {
    final Set<Option> handler;
    final Option opt1;
    final Option opt2;
    final Option opt3;
    final CommandLine cl;

    TestContext(Set<Option> handler, Option opt1, Option opt2, Option opt3, CommandLine cl) {
        this.handler = handler;
        this.opt1 = opt1;
        this.opt2 = opt2;
        this.opt3 = opt3;
        this.cl = cl;
    }
}

private TestContext createTestContext() {
    Set<Option> handler = new HashSet<>();

    DefaultParser parser = DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();

    Option opt1 = Option.builder()
            .option("d1")
            .deprecated()
            .build();

    Option opt2 = Option.builder()
            .option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();

    Option opt3 = Option.builder()
            .option("a")
            .build();

    Options options = new Options()
            .addOption(opt1)
            .addOption(opt2)
            .addOption(opt3);

    CommandLine cl = assertDoesNotThrow(
            () -> parser.parse(options, new String[] {"-d1", "-d2", "-a"}),
            "Parsing the command line threw an unexpected exception");

    return new TestContext(handler, opt1, opt2, opt3, cl);
}

