public void testIndexOf() {
    JsonArray a = new JsonArray();
    // Add the same value twice to test indexOf vs. lastIndexOf
    a.add(1);
    a.add(1);

    List<JsonElement> list = a.asList();

    // Verify indexOf for an existing JsonPrimitive
    assertWithMessage("indexOf should return 0 when searching for JsonPrimitive(1)")
        .that(list.indexOf(new JsonPrimitive(1))).isEqualTo(0);

    // Verify indexOf for a non‑existing JsonPrimitive
    assertWithMessage("indexOf should return -1 when searching for JsonPrimitive(2) which is not present")
        .that(list.indexOf(new JsonPrimitive(2))).isEqualTo(-1);

    // Verify indexOf for null argument
    assertWithMessage("indexOf should return -1 when searching for null")
        .that(list.indexOf(null)).isEqualTo(-1);

    @SuppressWarnings({"unlikely-arg-type", "CollectionIncompatibleType"})
    int indexOfInt = list.indexOf(1); // should only contain JsonPrimitive(1)
    // Verify indexOf when searching with an incompatible type (int)
    assertWithMessage("indexOf should return -1 when searching with an incompatible type (int)")
        .that(indexOfInt).isEqualTo(-1);

    // Verify lastIndexOf for an existing JsonPrimitive
    assertWithMessage("lastIndexOf should return 1 for JsonPrimitive(1) when it appears twice")
        .that(list.lastIndexOf(new JsonPrimitive(1))).isEqualTo(1);

    // Verify lastIndexOf for a non‑existing JsonPrimitive
    assertWithMessage("lastIndexOf should return -1 for JsonPrimitive(2) which is not present")
        .that(list.lastIndexOf(new JsonPrimitive(2))).isEqualTo(-1);

    // Verify lastIndexOf for null argument
    assertWithMessage("lastIndexOf should return -1 when searching for null")
        .that(list.lastIndexOf(null)).isEqualTo(-1);
}

