    assertEquals("HTML output should normalize DOCTYPE to lowercase", "<!doctype html>", htmlOutput(base));
    assertEquals("XML output should preserve original DOCTYPE case", base, xmlOutput(base));

    String publicDoc = "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">";
    assertEquals("HTML output should preserve public DOCTYPE as is", publicDoc, htmlOutput(publicDoc));
    assertEquals("XML output should preserve public DOCTYPE as is", publicDoc, xmlOutput(publicDoc));

    String systemDoc = "<!DOCTYPE html SYSTEM \"exampledtdfile.dtd\">";
    assertEquals("HTML output should preserve system DOCTYPE as is", systemDoc, htmlOutput(systemDoc));
    assertEquals("XML output should preserve system DOCTYPE as is", systemDoc, xmlOutput(systemDoc));

    String legacyDoc = "<!DOCTYPE html SYSTEM \"about:legacy-compat\">";
    assertEquals("HTML output should preserve legacy system DOCTYPE as is", legacyDoc, htmlOutput(legacyDoc));
    assertEquals("XML output should preserve legacy system DOCTYPE as is", legacyDoc, xmlOutput(legacyDoc));
}

