/**
 * Copies a resource from the classpath to a temporary file inside the given directory.
 *
 * @param dir          the temporary directory provided by @TempDir
 * @param resourcePath the classpath resource path (e.g., "/htmltests/file.html")
 * @return a {@link File} pointing to the newly created temporary file
 * @throws IOException if an I/O error occurs during copying
 */
private static File copyResourceToTemp(File dir, String resourcePath) throws IOException {
    String fileName = new File(resourcePath).getName();
    File tempFile = new File(dir, fileName);
    try (InputStream is = DocumentTest.class.getResourceAsStream(resourcePath)) {
        if (is == null) {
            throw new IOException("Resource not found: " + resourcePath);
        }
        Files.copy(is, tempFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
    }
    return tempFile;
}

