public void testKeepsPreTextAtDepth_TextPreserved() {
    String html = "<pre><code><span><b>code\n\ncode</b></span></code></pre>";
    Document doc = Jsoup.parse(html);
    assertEquals("The extracted text should preserve line breaks inside <pre>", 
                 "code\n\ncode", 
                 doc.text());
}

@Test
public void testKeepsPreTextAtDepth_HtmlPreserved() {
    String html = "<pre><code><span><b>code\n\ncode</b></span></code></pre>";
    Document doc = Jsoup.parse(html);
    assertEquals("The HTML inside the body should remain unchanged after parsing", 
                 "<pre><code><span><b>code\n\ncode</b></span></code></pre>", 
                 doc.body().html());
}

@Test
public void testChildSizeWithMixedContent_ChildrenSize() {
    Document doc = Jsoup.parse("<table><tbody>\n<tr>\n<td>15:00</td>\n<td>sport</td>\n</tr>\n</tbody></table>");
    Element row = doc.selectFirst("table tbody tr");
    assertEquals("A <tr> element should have exactly 2 child <td> elements", 
                 2, 
                 row.childrenSize());
}

@Test
public void testChildSizeWithMixedContent_ChildNodeSize() {
    Document doc = Jsoup.parse("<table><tbody>\n<tr>\n<td>15:00</td>\n<td>sport</td>\n</tr>\n</tbody></table>");
    Element row = doc.selectFirst("table tbody tr");
    assertEquals("A <tr> element should have 5 child nodes including text nodes and elements", 
                 5, 
                 row.childNodeSize());
}

// Optional helper method for parsing HTML strings, if needed elsewhere
private Document parseDocument(String html) {
    return Jsoup.parse(html);
}
